'use client';

import { FC, useState } from 'react';
import { cn } from '@/lib/utils';
import { Calendar } from 'lucide-react';
import { format, addDays } from 'date-fns';

interface AvailabilitySelectorProps {
  onServiceChange?: (type: 'self' | 'chauffeur') => void;
  onDateChange?: (date: Date) => void;
}

const AvailabilitySelector: FC<AvailabilitySelectorProps> = ({ onServiceChange, onDateChange }) => {
  const [serviceType, setServiceType] = useState<'self' | 'chauffeur'>('self');
  const [selectedDate, setSelectedDate] = useState(new Date());

  // Generate 5 days starting from today
  const dates = Array.from({ length: 5 }, (_, i) => addDays(new Date(), i));

  const handleServiceToggle = (type: 'self' | 'chauffeur') => {
    setServiceType(type);
    onServiceChange?.(type);
  };

  const handleDateSelect = (date: Date) => {
    setSelectedDate(date);
    onDateChange?.(date);
  };

  return (
    <div className="flex flex-col gap-6">
      {/* Date Selector */}
      <div className="flex flex-col gap-3">
        <span className="text-sm font-semibold text-gray-700">Check Availability</span>
        <div className="flex items-center gap-2">
          {dates.map((date, idx) => {
            const isSelected = format(date, 'yyyy-MM-dd') === format(selectedDate, 'yyyy-MM-dd');
            return (
              <button
                key={idx}
                onClick={() => handleDateSelect(date)}
                className={cn(
                  'flex h-12 w-12 flex-col items-center justify-center rounded-xl border transition-all',
                  isSelected
                    ? 'border-[#3B82F6] bg-[#3B82F6] text-white shadow-lg shadow-blue-100'
                    : 'border-transparent bg-[#F3F4F6] text-gray-500 hover:border-gray-300',
                )}
              >
                <span className="text-[10px] font-bold uppercase">{format(date, 'dd')}</span>
                <span className="text-[10px] font-bold uppercase">{format(date, 'MMM')}</span>
              </button>
            );
          })}
          <button className="flex h-12 w-12 items-center justify-center rounded-xl border-2 border-dashed border-gray-200 bg-white text-gray-400 transition-all hover:border-gray-300 hover:text-gray-500">
            <Calendar className="h-5 w-5" />
          </button>
        </div>
      </div>

      {/* Service Selection */}
      <div className="flex flex-col gap-3">
        <span className="text-sm font-semibold text-gray-700">Available For</span>
        <div className="flex items-center gap-3">
          <button
            onClick={() => handleServiceToggle('self')}
            className={cn(
              'h-10 rounded-full border px-6 text-sm font-semibold transition-all',
              serviceType === 'self'
                ? 'border-black bg-black text-white'
                : 'border-gray-200 bg-white text-gray-600 hover:border-gray-300',
            )}
          >
            Self Drive
          </button>
          <button
            onClick={() => handleServiceToggle('chauffeur')}
            className={cn(
              'h-10 rounded-full border px-6 text-sm font-semibold transition-all',
              serviceType === 'chauffeur'
                ? 'border-black bg-black text-white'
                : 'border-gray-200 bg-white text-gray-600 hover:border-gray-300',
            )}
          >
            Chauffeur
          </button>
        </div>
      </div>
    </div>
  );
};

export default AvailabilitySelector;
