'use client';

import { useVehicle } from '@/app/axios';
import { useEffect, use } from 'react';
import { useTranslations } from 'next-intl';
import VehicleImageGallery from '@/components/car-components/VehicleImageGallery';
import VehicleSpecsTable from '@/components/car-components/VehicleSpecsTable';
import AvailabilitySelector from '@/components/car-components/AvailabilitySelector';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';

const Page = ({ params }: { params: Promise<{ id: string }> }) => {
  const { id } = use(params);
  const { vehicle, fetchVehicleById, isLoading, error } = useVehicle();
  const t = useTranslations('vehicleDetails');

  useEffect(() => {
    if (id) {
      fetchVehicleById(id);
    }
  }, [fetchVehicleById, id]);

  if (isLoading) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <div className="h-12 w-12 animate-spin rounded-full border-4 border-[#3B82F6] border-t-transparent shadow-sm"></div>
      </div>
    );
  }

  if (error || !vehicle) {
    return (
      <div className="global-container py-20 text-center">
        <h2 className="text-2xl font-bold text-gray-800">Vehicle Not Found</h2>
        <p className="mt-2 text-gray-600">
          {error || "The vehicle you're looking for doesn't exist or has been removed."}
        </p>
      </div>
    );
  }

  return (
    <main className="global-container py-8 md:py-16">
      <div className="grid grid-cols-1 gap-12 lg:grid-cols-2 lg:gap-24">
        {/* Left: Gallery */}
        <div className="flex flex-col gap-10">
          <VehicleImageGallery media={vehicle.media} model={vehicle.model} />
        </div>

        {/* Right: Info & Booking */}
        <div className="flex flex-col gap-10">
          {/* Header */}
          <div className="flex flex-col gap-4">
            <div className="flex items-center gap-3">
              <h1 className="text-4xl font-extrabold text-gray-900">
                {vehicle.make} {vehicle.model}
              </h1>
              <div className="flex gap-2">
                <Badge className="border-none bg-blue-50 px-3 py-1 font-semibold text-blue-600 hover:bg-blue-50">
                  {vehicle.isAvailable ? 'Available' : 'Unavailable'}
                </Badge>
                <Badge className="border-none bg-orange-50 px-3 py-1 font-semibold text-orange-600 hover:bg-orange-50">
                  {vehicle.bodyType}
                </Badge>
              </div>
            </div>
            <p className="text-lg font-medium text-gray-500">
              {vehicle.year} {vehicle.model} {vehicle.transmission} •{' '}
              <span className="text-gray-800">12 Rides available</span>
            </p>
          </div>

          {/* Availability & Service */}
          <AvailabilitySelector />

          {/* Pricing & CTA */}
          <div className="flex flex-col gap-6">
            <div className="flex items-baseline gap-2">
              <span className="text-4xl font-extrabold text-gray-900">
                {vehicle.pricePerDay} {vehicle.currency || 'USD'}/Day
              </span>
              <span className="text-sm font-semibold text-blue-500">
                [{vehicle.depositPercentage || '35'}% Deposit]
              </span>
            </div>

            <Button className="h-14 w-48 rounded-2xl bg-[#3B82F6] text-lg font-bold shadow-lg shadow-blue-100 transition-all hover:bg-[#2563EB]">
              Make Payment
            </Button>
          </div>

          {/* Specifications */}
          <VehicleSpecsTable vehicle={vehicle} />
        </div>
      </div>
    </main>
  );
};

export default Page;
